import com.koios.game.arpg.*;import com.koios.game.model.item.Item;import com.koios.game.model.player.Player;
/** Exact physical gem ownership across swaps, independent supports and reconnect. */
public final class PhysicalGemOwnershipCheck {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static void same(Item a,Item b,String why){check(a.getRoll().getInstanceId().equals(b.getRoll().getInstanceId())&&a.getRoll().getGem().level==b.getRoll().getGem().level,why);}
 public static void main(String[] args)throws Exception{
 PrototypeIntegrationCheck.loaded();Player p=PrototypeIntegrationCheck.player("gemownership",93);PrototypeIntegrationCheck.idle(p);p.getArpgProgress().award(1000000);
 for(int level:new int[]{20,1,7,1}){Item gem=MapRuns.gem(level,false,0);p.getInventory().set(0,gem);ArpgSkills.handle(p,"arpgskill socketactive 0 0");check(p.getInventory().get(0)==null&&p.getArpgSkills().skillLevel(0)==level,"Active uses actual input level");ArpgSkills.handle(p,"arpgskill unsocketactive 0");same(gem,p.getInventory().get(0),"Active retains UUID and level");p.getInventory().set(0,null);}
 for(String command:new String[]{"arpgskill assign 0 0","arpgskill attach 0 0","arpgskill support 0 0","arpgskill move 0 1 0"}){ArpgSkills.handle(p,command);check(p.getArpgSkills().assigned(0)==-1&&p.getArpgSkills().owned(0)==0,"Empty ledger cannot re-enable retired route: "+command);}ArpgSkills.handle(p,"arpgskill cast 0");check(p.getArpgSkills().getMana()==50&&p.getArpgSkills().getCooldown(0)==0,"Direct cast packet cannot bypass empty sockets");for(String invalid:new String[]{"arpgskill unsocket -1 0","arpgskill unsocket 5 0","arpgskill unsocket 0 -1","arpgskill unsocket 0 32"}){ArpgSkills.handle(p,invalid);check(p.getInventory().size()==0,"Malformed unsocket rejected: "+invalid);}ArpgSkills.handle(p,"arpgskill unsocketactive 0");check(p.getInventory().size()==0,"Last-unsocket assign replay cannot mint free gem");
SkillState state=p.getArpgSkills();state.socketActive(0,0,1,100);state.socketActive(1,1,1,100);
 Item high=MapRuns.gem(20,true,2),low=MapRuns.gem(1,true,2);p.getInventory().set(0,high);p.getInventory().set(1,low);for(String invalid:new String[]{"-1","999","bad"}){ArpgSkills.handle(p,"arpgskill socket 0 0 "+invalid);check(p.getInventory().get(0)==high&&state.owned(2)==0,"Malformed drop socket cannot consume gem: "+invalid);}ArpgSkills.handle(p,"arpgskill socket 0 0 2");ArpgSkills.handle(p,"arpgskill socket 1 1 2");check(state.supportLevel(0,2)==20&&state.supportLevel(1,2)==1,"Support copies retain independent levels");check(Math.abs(state.effectiveness(0)/(1.8)-1.49)<1e-8&&Math.abs(state.effectiveness(1)/.9-1.3)<1e-8,"Actual damage uses independent support levels");
 // Reject a forged second copy before changing either inventory or ownership.
p.getInventory().set(2,high.copy());String beforeLedger=state.savePhysicalGems();ArpgSkills.handle(p,"arpgskill socket 2 1 2");check(p.getInventory().get(2)!=null&&beforeLedger.equals(state.savePhysicalGems()),"Duplicate UUID socket cannot consume or overwrite");p.getInventory().set(2,null);
int messages=((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets.size();String beforeRemoval=state.savePhysicalGems();ArpgSkills.handle(p,"arpgskill unsocketactive 0");check(state.assigned(0)==0&&state.getSupport(0)==4&&beforeRemoval.equals(state.savePhysicalGems()),"Active removal cannot hide attached supports");boolean feedback=false;for(int at=messages;at<((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets.size();at++){com.koios.network.GamePacket packet=((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets.get(at);if(packet.getOpcode()==253){byte[] bytes=new byte[packet.getSize()];packet.getBuffer().getBytes(packet.getBuffer().readerIndex(),bytes);if(new String(bytes,"windows-1252").contains("Remove support gems first"))feedback=true;}}check(feedback,"Rejected active removal sends clear player feedback");
String physical=state.savePhysicalGems();SkillState reload=new SkillState();reload.loadLevels(state.saveLevels());reload.loadOwned(state.saveOwned());reload.loadHotbar(state.saveHotbar());reload.setSupport(0,state.getSupport(0));reload.setSupport(1,state.getSupport(1));reload.loadPhysicalGems(physical);same(high,reload.socketedGem(0,2),"Reconnect high support identity");same(low,reload.socketedGem(1,2),"Reconnect low support identity");check(reload.supportLevel(1,2)==1,"Reconnect cannot promote low support");
 state.activate();String[] packet=state.update(50).split("\\|");check(packet[28].equals("20")&&packet[31].equals("1"),"Client receives per-skill levels");ArpgSkills.handle(p,"arpgskill detach 1 2");check(state.getSupport(1)==4,"Legacy mask command cannot detach physical gem");
 ArpgSkills.handle(p,"arpgskill unsocket 1 2");same(low,p.getInventory().get(0),"Low support returns unchanged");ArpgSkills.handle(p,"arpgskill unsocket 0 2");same(high,p.getInventory().get(1),"High support returns unchanged");
 // Full inventory leaves the actual roll socketed and replay cannot duplicate it.
p.getInventory().set(0,null);p.getInventory().set(1,null);p.getInventory().set(0,low);ArpgSkills.handle(p,"arpgskill socket 0 1 2");for(int slot=0;slot<28;slot++)p.getInventory().set(slot,new Item(385));beforeLedger=state.savePhysicalGems();ArpgSkills.handle(p,"arpgskill unsocket 1 2");check(beforeLedger.equals(state.savePhysicalGems())&&state.getSupport(1)==4,"Full inventory removal atomic");
SkillState legacy=new SkillState();legacy.loadLevels("1,1,7,8,9");legacy.loadOwned("1,0,0");legacy.attach(0,0,true);check(legacy.supportLevel(0,0)==7,"Legacy levels remain usable without invented migration");
 try{reload.loadPhysicalGems("invalid");throw new AssertionError("Malformed ledger accepted");}catch(IllegalArgumentException expected){check(reload.savePhysicalGems().equals(physical),"Malformed load atomic");}
 for(int supportLevel:new int[]{1,20}){SkillState speed=new SkillState();speed.socketActive(0,2,1,100);speed.learnSupport(1,supportLevel,100);speed.attach(2,1,true);speed.recordGem(2,1,MapRuns.gem(supportLevel,true,1));check(speed.spend(2,1),"Speed fixture casts");check(speed.getCooldown(2)==(supportLevel==1?7:6),"Physical attack speed remains valid");}
java.lang.reflect.Method loader=com.koios.game.model.player.io.PlayerLoader.class.getDeclaredMethod("parseEssentials",Player.class,String.class,String.class);loader.setAccessible(true);Player loaded=PrototypeIntegrationCheck.player("gemledgerload",94);loader.invoke(null,loaded,"essential-arpg-physical-gems",physical);same(low,loaded.getArpgSkills().socketedGem(1,2),"Actual player loader restores exact low roll");
System.out.println("Passed "+checks+" physical gem ownership checks.");
 }
}
